async function fixture() {
  vi.useFakeTimers();
  const f = await analysisVersionFixture(false);
  const network = vi.fn(() => {
    throw Error("No network is permitted in retrieval-quality fixtures.");
  });
  vi.stubGlobal("fetch", network);
  const idToKey = new Map<string, string>();
  const keyToId = new Map<string, typeof f.sourceId>();
  for (const post of posts) {
    vi.setSystemTime(Date.now() + 2100);
    const sourceId = await f.owner.mutation(api.product.capture, {
      organizationId: f.org,
      key: `quality-${post.key}`,
      kind: "text",
      title: post.title,
      text: `Private synthetic transcript for ${post.key}, never returned by search.`,
      rightsAttested: true,
    });
    await f.t.run(async (ctx) => {
      await ctx.db.patch(sourceId, {
        state: "ready",
        linkPreview: {
          state: "ready",
          authorName: post.author,
          updatedAt: Date.now(),
        },
        analysis: {
          summary: post.title,
          insights: post.ideas.map(([title, claim], index) => ({
            id: `${post.key}-${index}`,
            title,
            claim: `${claim} This workflow is documented.`,
            categories: [post.category],
            evidence: [],
          })),
        },
      });
      await syncDashboardCard(
        ctx,
        "sources",
        sourceId,
        (await ctx.db.get(sourceId))!,
      );
    });
    idToKey.set(sourceId, post.key);
    keyToId.set(post.key, sourceId);
  }
  vi.stubEnv("WORKSPACE_SEARCH_ENABLED", "true");
  vi.stubEnv("WORKSPACE_SEARCH_CURSOR_SECRET", "b".repeat(64));
  for (let step = 0; step < 40; step++) {
    const progress = await f.t.mutation(internal.workspaceSearch.bootstrap, {
      organizationId: f.org,
    });
    if (progress.done) break;
    expect(step).toBeLessThan(39);
  }
  const search = async (
    query: string,
    target: "posts" | "insights" | "both" = "insights",
  ) => {
    const matchedPostKeys = new Set<string>(),
      matchIds = new Set<string>();
    let cursor: string | undefined;
    let pages = 0,
      responseBytes = 0,
      candidates = 0,
      loadedBytes = 0,
      indexedComplete = false;
    do {
      const page = workspaceSearchOutput.parse(
        await f.assistant.query(internal.workspaceSearch.search, {
          profileId: f.org,
          mode: "ranked_v1",
          query,
          target,
          ...(cursor ? { cursor } : {}),
        }),
      );
      const bytes = new TextEncoder().encode(JSON.stringify(page)).byteLength;
      expect(bytes).toBeLessThanOrEqual(workspaceSearchLimits.responseBytes);
      expect(page.examined_sources).toBeLessThanOrEqual(
        workspaceSearchLimits.sourceHydrations,
      );
      expect(page.scanned_candidates).toBeLessThanOrEqual(
        workspaceSearchLimits.candidatesPerPage,
      );
      expect(page.session_candidates).toBeLessThanOrEqual(
        workspaceSearchLimits.candidatesPerSession,
      );
      expect(page.posts.map((post) => post.id).length).toBe(
        new Set(page.posts.map((post) => post.id)).size,
      );
      const byPost = new Map(page.posts.map((post) => [post.id, post]));
      for (const match of page.matches) {
        expect(matchIds.has(match.id), `duplicate ${match.id}`).toBe(false);
        matchIds.add(match.id);
        const post = byPost.get(match.post_id)!;
        expect(post).toBeTruthy();
        expect(idToKey.has(post.reference.sourceId)).toBe(true);
        matchedPostKeys.add(idToKey.get(post.reference.sourceId)!);
      }
      expect(JSON.stringify(page)).not.toContain(
        "Private synthetic transcript",
      );
      responseBytes += bytes;
      candidates += page.scanned_candidates;
      loadedBytes += page.loaded_bytes;
      pages++;
      indexedComplete = !page.has_more;
      cursor = page.next_cursor ?? undefined;
      expect(pages).toBeLessThanOrEqual(12);
    } while (cursor);
    return {
      postKeys: [...matchedPostKeys].sort(),
      matches: matchIds.size,
      pages,
      responseBytes,
      candidates,
      loadedBytes,
      indexedComplete,
    };
  };
  return { ...f, idToKey, keyToId, network, search };
}

it("records lexical hits, semantic-only misses and bounded host-query expansion against explicit synthetic goals", async () => {
  const f = await fixture();
  const cases = [
    {
      name: "exact term",
      query: "signup",
      target: "insights" as const,
      expected: ["signup-form"],
      goal: ["signup-form"],
    },
    {
      name: "exact multiword",
      query: "Exponential backoff",
      target: "insights" as const,
      expected: ["retry-jitter"],
      goal: ["retry-jitter"],
    },
    {
      name: "paraphrase",
      query: "make registration effortless",
      target: "insights" as const,
      expected: [],
      goal: ["activation-checklist", "signup-form"],
    },
    {
      name: "category word",
      query: "product_design",
      target: "insights" as const,
      expected: [
        "accessible-drawer",
        "activation-checklist",
        "assistant-progress",
        "signup-form",
      ],
      goal: [
        "accessible-drawer",
        "activation-checklist",
        "assistant-progress",
        "signup-form",
      ],
    },
    {
      name: "creator metadata",
      query: "Jane Rivera",
      target: "posts" as const,
      expected: ["signup-form"],
      goal: ["signup-form"],
    },
    {
      name: "exact title",
      query: "Canonical evidence storage",
      target: "posts" as const,
      expected: ["canonical-storage"],
      goal: ["canonical-storage"],
    },
    {
      name: "reference as search text",
      query: f.keyToId.get("signup-form")!,
      target: "posts" as const,
      expected: [],
      goal: ["signup-form"],
    },
  ];
  const measurements = [];
  for (const scenario of cases) {
    const observed = await f.search(scenario.query, scenario.target);
    expect(observed.postKeys, scenario.name).toEqual(scenario.expected);
    expect(observed.indexedComplete).toBe(true);
    measurements.push({
      name: scenario.name,
      query:
        scenario.name === "reference as search text"
          ? "<exact saved source ID>"
          : scenario.query,
      expectedGoal: scenario.goal,
      observed,
      ...(scenario.name === "reference as search text"
        ? { route: "exact fetch, not full-text search" }
        : {}),
    });
  }
  const expandedQueries = ["signup", "onboarding"];
  const expanded = await Promise.all(
    expandedQueries.map((query) => f.search(query)),
  );
  const expandedKeys = [
    ...new Set(expanded.flatMap((value) => value.postKeys)),
  ].sort();
  expect(expandedKeys).toEqual(["activation-checklist", "signup-form"]);
  const duplicateEvidence = await f.search("signup");
  expect(duplicateEvidence.matches).toBe(2);
  expect(duplicateEvidence.postKeys).toHaveLength(1);
  const direct = knowledgeFetchStructuredOutput.parse(
    await f.assistant.query(internal.assistant.fetch, {
      profileId: f.org,
      id: f.keyToId.get("signup-form")!,
      format: "structured_v1",
    }),
  );
  expect(direct.analysis.insights).toHaveLength(2);
  const broad = await f.search("workflow");
  expect(broad.postKeys).toEqual(posts.map((post) => post.key).sort());
  expect(broad.matches).toBe(17);
  expect(broad.pages).toBeGreaterThan(1);
  expect(f.network).not.toHaveBeenCalled();
  if (process.env.WRITE_RETRIEVAL_QUALITY_RECEIPT === "1")
    writeFileSync(
      "outputs/retrieval-quality-20261101.json",
      JSON.stringify(
        {
          date: "2026-11-01",
          environment:
            "convex-test through actual workspaceSearch.search handler; lexical simulator, not production BM25/latency",
          syntheticPosts: posts.length,
          extraFoundationPosts: 1,
          newModelCalls: 0,
          newNetworkCalls: 0,
          measurements,
          hostExpansion: {
            queries: expandedQueries,
            expectedGoal: ["activation-checklist", "signup-form"],
            observedPostKeys: expandedKeys,
            responseBytes: expanded.reduce(
              (total, value) => total + value.responseBytes,
              0,
            ),
          },
          broadDiscovery: broad,
          limits:
            "Backend JSON bytes and instrumented serialized get bytes are not database billing, MCP envelope size or host tokens.",
        },
        null,
        2,
      ) + "\n",
    );
});

it("retrieves broad lexical matches through bounded pages without duplicate IDs or loading transcript bodies", async () => {
  const f = await fixture();
  const result = await f.search("workflow");
  expect(result.postKeys).toEqual(posts.map((post) => post.key).sort());
  expect(result.matches).toBe(17);
  expect(result.pages).toBeGreaterThan(1);
  expect(result.indexedComplete).toBe(true);
  expect(f.network).not.toHaveBeenCalled();
});

it("does not broaden a missed topic query into another workspace", async () => {
  const f = await fixture();
  const other = await f.owner.mutation(api.organizations.create, {
    name: "Separate quality collection",
  });
  const id = await f.owner.mutation(api.product.capture, {
    organizationId: other,
    kind: "text",
    key: "quality-isolated-post",
    title: "Treasury planning",
    text: "Separate collection data",
    rightsAttested: true,
  });
  await f.t.run(async (ctx) => {
    await ctx.db.patch(id, {
      state: "ready",
      analysis: {
        summary: "Treasury",
        insights: [
          {
            id: "treasury-plan",
            title: "Treasury reserves",
            claim: "Keep a treasury reserve.",
            evidence: [],
          },
        ],
      },
    });
    await syncDashboardCard(ctx, "sources", id, (await ctx.db.get(id))!);
  });
  await f.t.mutation(internal.workspaceSearch.refreshSource, {
    organizationId: other,
    sourceId: id,
  });
  expect(
    await f.t.run((ctx) =>
      ctx.db
        .query("workspaceSearchDocuments")
        .withIndex("by_post", (q) => q.eq("organizationId", other))
        .take(2),
    ),
  ).toHaveLength(2);
  expect((await f.search("treasury")).postKeys).toEqual([]);
  await expect(
    f.assistant.query(internal.assistant.fetch, {
      profileId: f.org,
      id,
      format: "structured_v1",
    }),
  ).rejects.toThrow(/FORBIDDEN/);
  expect(f.network).not.toHaveBeenCalled();
});
